<?php declare(strict_types=1); $this->layout('layouts/default',['title'=>$title,'currentPage'=>'media']); ?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">CONTEÚDO</p><h2>Biblioteca de mídia</h2><p>Originais, recortes, texto alternativo e associações com conteúdo.</p></div><span class="studio-badge"><?= count($files) ?> imagem(ns)</span></header>
<form class="studio-form-card studio-upload-card" method="post" enctype="multipart/form-data"><?= $this->csrf() ?><input type="hidden" name="action" value="upload"><div class="studio-field"><label for="image">Nova imagem — JPG, PNG, GIF ou WebP, até 8 MB</label><input id="image" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp" required></div><button>Enviar imagem</button></form>
<form class="studio-filter-bar studio-single-filter" method="get"><label><span>Busca</span><input name="q" value="<?= $this->e($search) ?>" placeholder="Nome ou texto alternativo"></label><button>Buscar</button><a href="/admin/media">Limpar</a></form>
<div class="studio-media-grid"><?php if($files===[]):?><p class="studio-panel studio-empty">Nenhuma imagem enviada.</p><?php endif;?><?php foreach($files as $file):?><article class="studio-panel studio-media-card"><img src="/admin/media/file/<?= (int)$file['id'] ?>" alt="<?= $this->e($file['alt_text']??'') ?>"><div><h3><?= $this->e($file['name']) ?></h3><p><?= (int)$file['width'] ?> × <?= (int)$file['height'] ?> · <?= $this->e(number_format(((int)$file['size'])/1024,1,',','.')) ?> KB</p><p><span class="studio-status"><?= (int)$file['usage_count'] ?> associação(ões)</span><?= $file['parent_id']?' · Recorte derivado':'' ?></p></div>
<form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="metadata"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><label><span>Texto alternativo</span><input name="alt_text" maxlength="255" value="<?= $this->e($file['alt_text']??'') ?>" placeholder="Descreva a imagem"></label><button>Salvar descrição</button></form>
<details><summary>Criar recorte</summary><form class="studio-crop-form" method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="crop"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><?php foreach(['crop_x'=>'X','crop_y'=>'Y','crop_width'=>'Largura','crop_height'=>'Altura'] as $name=>$label):?><label><span><?= $label ?></span><input type="number" name="<?= $name ?>" min="0" value="<?= str_contains($name,'width')?(int)$file['width']:(str_contains($name,'height')?(int)$file['height']:0) ?>" required></label><?php endforeach;?><button>Criar cópia recortada</button></form></details>
<form method="post"><?= $this->csrf() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$file['id'] ?>"><button class="studio-danger-button"<?= (int)$file['usage_count']>0?' disabled title="Imagem em uso"':'' ?> onclick="return confirm('Excluir esta imagem?')">Excluir</button></form></article><?php endforeach;?></div></section>
